registry_names = {'activate_plugin', 'append_file', 'benchmark_skill', 'board_add', 'board_delete', 'board_move', ...}
def test_toolset_maps_only_name_real_tools(registry_names): """Both toolset catalogs — the scoping gate the agent actually uses AND the JAEGER_TOOLSETS env bundles — must only reference registered tools. Stale entries either hide a real tool from a restricted surface or advertise a phantom one (review 2026-07-04 found the removed kanban umbrella, the renamed `skill`, never-registered read_traits/adjust_trait, and seven pre-rename computer_* names lingering here).""" from jaeger_agent.skill_registry.toolset_scoping import CORE, TOOLSETS from jaeger_agent.schemas.tool_bundles import JAEGER_TOOLSETS offenders: list[str] = [] for name in CORE: if name not in registry_names: offenders.append(f"toolset_scoping.CORE: {name!r}") for ts_name, members in TOOLSETS.items(): for name in members: if name not in registry_names: offenders.append(f"toolset_scoping.TOOLSETS[{ts_name}]: {name!r}") for ts_name, spec in JAEGER_TOOLSETS.items(): for name in spec.get("tools", []): if name not in registry_names: offenders.append(f"tool_bundles[{ts_name}]: {name!r}") > assert not offenders, ( "toolset catalogs naming unregistered tools:\n " + "\n ".join(offenders) ) E AssertionError: toolset catalogs naming unregistered tools: E toolset_scoping.TOOLSETS[computer_use]: 'computer_use' E tool_bundles[computer]: 'computer_use' E tool_bundles[computer]: 'computer_do' E tool_bundles[computer]: 'computer_look' E tool_bundles[computer]: 'computer_screenshot' E tool_bundles[computer]: 'computer_read_screen' E tool_bundles[computer]: 'computer_open_app' E tool_bundles[computer]: 'computer_click' E tool_bundles[computer]: 'computer_type_text' E tool_bundles[computer]: 'computer_press_key' E tool_bundles[computer]: 'computer_menu_select' E tool_bundles[computer_umbrella_only]: 'computer_use' E tool_bundles[computer_umbrella_only]: 'computer_do' E tool_bundles[full]: 'computer_use' E assert not ["toolset_scoping.TOOLSETS[computer_use]: 'computer_use'", "tool_bundles[computer]: 'computer_use'", "tool_bundles[com...omputer_look'", "tool_bundles[computer]: 'computer_screenshot'", "tool_bundles[computer]: 'computer_read_screen'", ...]
